<style>
    .ho-band{padding:20px;background:#e8f4f0;border-top:3px solid #0f766e;margin:0 0 22px;min-width:0}
    .ho-band--blue{background:#edf4fc;border-top-color:#15477a}.ho-band--yellow{background:#fff8dc;border-top-color:#f1c40f}
    .ho-band h2{margin:0 0 16px;font-size:19px;color:#15477a;display:flex;align-items:center;gap:10px}.ho-band h2 svg{width:22px;height:22px;flex-shrink:0}
    .ho-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.ho-grid>*{min-width:0}.ho-grid .span-2{grid-column:1/-1}
    .ho-filter{display:grid;grid-template-columns:minmax(0,2fr) repeat(2,minmax(0,1fr)) auto;gap:14px;align-items:end}
    .ho-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-bottom:22px}.ho-metric{padding:18px;background:#edf4fc;border:1px solid #cfdeec;border-radius:6px}.ho-metric:nth-child(2){background:#e7f4f0;border-color:#bcded5}.ho-metric:nth-child(3){background:#fff8dc;border-color:#ead88b}.ho-metric strong{display:block;font-size:28px;color:#15477a;margin-top:7px}
    .ho-table{width:100%;border-collapse:collapse;table-layout:fixed}.ho-table th{text-align:left;background:#edf4fc;padding:14px}.ho-table td{padding:16px 14px;border-bottom:1px solid #dce5eb;vertical-align:top;overflow-wrap:anywhere}.ho-table small{display:block;margin-top:5px;color:#627486}.ho-table a{overflow-wrap:anywhere}.ho-table .button{white-space:nowrap;min-width:76px;overflow-wrap:normal}.ho-table .badge{white-space:nowrap;overflow-wrap:normal}
    .ho-steps{list-style:none;margin:0;padding:0}.ho-steps li{display:grid;grid-template-columns:34px minmax(0,1fr) auto;align-items:center;gap:14px;padding:17px 0;border-bottom:1px solid #cfe0db}.ho-steps strong{display:block;margin-bottom:5px}.ho-steps p{margin:0;color:#52687a}.ho-steps svg{width:23px;height:23px;color:#0f766e}.ho-steps .actions{justify-content:flex-end}
    .ho-files{list-style:none;padding:0;margin:0}.ho-files li{padding:18px 0;border-bottom:1px solid #cfe0db;overflow-wrap:anywhere}.ho-files small{display:block;margin:6px 0;color:#52687a}.ho-files .actions{margin-top:12px;flex-wrap:wrap}.ho-files form{display:flex;gap:10px;flex-wrap:wrap;width:100%;margin-top:10px}.ho-files form .input{flex:1 1 200px;min-width:0}
    .ho-audit{list-style:none;margin:0;padding:0}.ho-audit li{padding:12px 0;border-bottom:1px solid #dce5eb;overflow-wrap:anywhere}.ho-audit small{display:block;color:#627486;margin-top:5px}
    @media(max-width:1000px){.ho-filter{grid-template-columns:repeat(2,minmax(0,1fr))}.ho-steps li{grid-template-columns:28px minmax(0,1fr)}.ho-steps .actions{grid-column:2;justify-content:flex-start}}
    @media(max-width:1100px){.ho-table colgroup,.ho-table thead{display:none}.ho-table tr{display:block;border-bottom:1px solid #dce5eb;padding:12px 0}.ho-table td{display:block;border:0;padding:8px 0}.ho-table td[data-label]::before{content:attr(data-label);display:block;font-size:13px;color:#627486;margin-bottom:5px}}
    @media(max-width:620px){.ho-grid,.ho-filter{grid-template-columns:minmax(0,1fr)}.ho-grid .span-2{grid-column:auto}.ho-band{padding:16px}.ho-metrics{gap:8px}.ho-metric{padding:12px}.ho-metric strong{font-size:24px}}
</style>
